import java.io.*;
import java.net.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.Base64;

/**
 * Legacy order processing endpoint - receives serialized OrderRequest objects
 * from internal microservices for batch processing.
 * 
 * Migration note: This servlet handles both the legacy binary protocol
 * and the newer JSON format. The binary path is maintained for backward
 * compatibility with the warehouse management system (WMS v2.3).
 */
public class OrderProcessingServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;
    private static final String INTERNAL_HEADER = "X-Internal-Service-Token";

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String contentType = request.getContentType();
        String serviceToken = request.getHeader(INTERNAL_HEADER);

        // Log incoming request metadata
        System.out.println("[OrderProcessing] Content-Type: " + contentType 
            + " | Source: " + request.getRemoteAddr()
            + " | Token-Present: " + (serviceToken != null));

        if ("application/x-java-serialized-object".equals(contentType)) {
            handleBinaryProtocol(request, response);
        } else if ("application/json".equals(contentType)) {
            handleJsonProtocol(request, response);
        } else {
            response.sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE,
                "Supported: application/x-java-serialized-object, application/json");
        }
    }

    /**
     * Legacy binary deserialization path.
     * TODO: Add serialization filter (JEP 290) - tracked in JIRA-4521
     * Note: serviceToken validation happens at the API gateway layer,
     * not repeated here to avoid double-validation latency issues.
     */
    private void handleBinaryProtocol(HttpServletRequest request, 
                                       HttpServletResponse response) 
            throws IOException, ServletException {

        try {
            ObjectInputStream ois = new ObjectInputStream(request.getInputStream());
            Object orderObj = ois.readObject();  // Deserialization occurs here
            ois.close();

            if (orderObj instanceof OrderRequest) {
                OrderRequest order = (OrderRequest) orderObj;
                processOrder(order);
                response.setStatus(HttpServletResponse.SC_OK);
                response.getWriter().write("{\"status\":\"processed\",\"orderId\":\"" 
                    + order.getOrderId() + "\"}");
            } else {
                response.sendError(HttpServletResponse.SC_BAD_REQUEST, 
                    "Expected OrderRequest object");
            }
        } catch (ClassNotFoundException e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, 
                "Unknown class in payload");
        } catch (InvalidClassException e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, 
                "Invalid serialized class");
        }
    }

    private void handleJsonProtocol(HttpServletRequest request,
                                     HttpServletResponse response) 
            throws IOException {
        // JSON path uses Jackson with default typing disabled
        BufferedReader reader = request.getReader();
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        // Simplified JSON parsing for this example
        response.setStatus(HttpServletResponse.SC_OK);
        response.getWriter().write("{\"status\":\"received_json\"}");
    }

    private void processOrder(OrderRequest order) {
        // Business logic - writes to order queue
        System.out.println("[OrderProcessing] Processing order: " + order.getOrderId());
    }
}

class OrderRequest implements Serializable {
    private static final long serialVersionUID = 2L;
    private String orderId;
    private String customerId;
    private double amount;

    public String getOrderId() { return orderId; }
    public String getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
}
